72	static int task_setup(FAR struct tcb_s *tcb, const char *name, main_t entry,
73	                      FAR const posix_spawn_file_actions_t *actions,
74	                      FAR const posix_spawnattr_t *attr,
75	                      FAR char * const argv[], FAR char * const envp[],
76	                      int ttype)
77	{
78	  size_t stacksize = attr->stacksize;
79	#ifndef CONFIG_BUILD_KERNEL
80	  FAR void *stack = attr->stackaddr;
81	#else
82	  FAR void *stack = NULL;
83	#endif
84	  int priority = attr->priority;
85	  int ret;
86	
87	  /* Duplicate the parent tasks environment */
88	
89	  ret = env_dup(tcb->group->tg_info, envp);
90	  if (ret >= 0)
91	    {
92	      /* Associate file descriptors with the new task */
93	
94	      ret = group_setuptaskfiles(tcb, actions, true);
95	      if (ret >= 0)
96	        {
97	          /* Set the task name */
98	
99	          nxtask_setup_name(tcb, name);
100	
101	          if (stack)
102	            {
103	              /* Use pre-allocated stack */
104	
105	              ret = up_use_stack(tcb, stack, stacksize, ttype);
106	            }
107	          else
108	            {
109	              /* Allocate the stack for the TCB */
110	
111	              ret = up_create_stack(tcb, stacksize, ttype);
112	            }
113	
114	          if (ret >= OK)
115	            {
116	              /* Initialize thread local storage */
117	
118	              ret = tls_init_info(tcb);
119	              if (ret >= OK)
120	                {
121	#if defined(CONFIG_ARCH_ADDRENV) && defined(CONFIG_ARCH_KERNEL_STACK)
122	                  /* Allocate the kernel stack */
123	
124	                  if (ttype != TCB_FLAG_TTYPE_KERNEL)
125	                    {
126	                      ret = up_addrenv_kstackalloc(tcb);
127	                    }
128	#endif
129	
130	                  if (ret >= OK)
131	                    {
132	                      /* Setup to pass parameters to the new task */
133	
134	                      ret = nxtask_setup_stackargs(tcb, name, argv);
135	                      if (ret >= OK)
136	                        {
137	                          /* Initialize the task control block */
138	
139	                          ret = nxtask_setup_scheduler(tcb, priority,
140	                                                       nxtask_start,
141	                                                       entry, ttype);
142	                        }
143	                    }
144	                }
145	            }
146	
147	          if (ret < OK && !stack && tcb->stack_alloc_ptr)
148	            {
149	#ifdef CONFIG_BUILD_KERNEL
150	              /* If the exiting thread is not a kernel thread, then it has
151	               * an address environment. Don't bother to release the stack
152	               * memory in this case... There is no point since the memory
153	               * lies in the user memory region that will be destroyed anyway
154	               * (and the address environment has probably already been
155	               * destroyed at this point.. so we would crash if we even tried
156	               * it).  But if this is a privileged group, then we still have
157	               * to release the memory using the kernel allocator.
158	               */
159	
160	              if (ttype == TCB_FLAG_TTYPE_KERNEL)
161	#endif
162	                {
163	                  up_release_stack(tcb, ttype);
164	                }
165	            }
166	        }
167	    }
168	
169	  return ret;
170	}
